//! Goldens recorded on 2026-11-15 with native PyPI cea==3.3.4 (macOS arm64).
//! NASA source/data: 2f79a647e85737742fb08a127da00d1ea1d069da, no transport/ions.
//! RP-1311 example 7: H2/O2/Ar mole fractions .05/.05/.90, 300 K,
//! 10/20 mmHg, all seven speeds and both incident modes. The 1000 m/s
//! equilibrium cases return native error 9 (last valid, not converged).
//! Reflections cover all four modes at 1400 m/s, 10 mmHg. Air is .79 N2/.21 O2
//! by mole, 300 K, 1 bar, Mach 3/6/10. `air5` explicitly restricts products to
//! N2/O2/NO/N/O at Mach 10: unrestricted equilibrium reflection is currently
//! rejected by Solver::solve because appreciable N2O exceeds its 6000 K fit.
//!
//! Reproduction with the native Python API (explicit flags avoid native defaults):
//! cea.init(path=str(Path(cea.__file__).parent / "data"), trans=False)
//! reactants = cea.Mixture(names)
//! products = cea.Mixture(names, products_from_reactants=True)  # or air5 pool
//! weights = reactants.moles_to_weights(np.array(moles))
//! solver = cea.ShockSolver(products, reactants=reactants)
//! soln = cea.ShockSolution(solver, reflected=reflected)
//! solver.solve(soln, weights, 300., pressure_pa / 1e5, u1=speed,
//!              reflected=reflected, incident_frozen=incident_frozen,
//!              reflected_frozen=reflected_frozen)  # air uses Mach1=speed
//! Record only soln.converged and soln.last_error == 0. Convert bar to Pa,
//! kJ/kg to J/kg, kJ/kg/K to J/kg/K. Reflected-frozen cp_fr is uninitialized
//! in native: obtain Cp independently with products.calc_property(cea.FROZEN_CP,
//! product_mass_weights, soln.T[2]) (already J/kg/K). NASA's reported gamma and
//! sonic speed deliberately retain the incident frozen-Cp basis.
use cea_rs::{
    Error,
    shock::{ShockSpeed, ShockStation},
    solver::Solver,
    thermo::Reactant,
};

fn model(kind: &str) -> (Solver, Vec<f64>) {
    let (names, moles): (&[&str], &[f64]) = match kind {
        "rp7" => (&["H2", "O2", "Ar"], &[0.05, 0.05, 0.9]),
        _ => (&["N2", "O2"], &[0.79, 0.21]),
    };
    let reactants: Vec<_> = names.iter().map(|n| Reactant::named(n).unwrap()).collect();
    let weights = reactants
        .iter()
        .zip(moles)
        .map(|(r, n)| r.molecular_weight * n)
        .collect();
    let only = (kind == "air5").then(|| ["N2", "O2", "NO", "N", "O"].map(String::from).to_vec());
    (
        Solver::new(reactants, true, false, only, vec![]).unwrap(),
        weights,
    )
}

fn close(actual: f64, expected: f64, label: &str) {
    let error = (actual - expected).abs() / expected.abs().max(1e-30);
    assert!(
        actual.is_finite() && error <= 1e-4,
        "{label}: {actual} != {expected}, relative error {error}"
    );
}

fn check_station(station: &ShockStation, expected: &[f64], label: &str) {
    let s = &station.state;
    let actual = [
        s.temperature_k,
        s.pressure_pa,
        s.density_kg_m3,
        s.enthalpy_j_kg,
        s.energy_j_kg,
        s.entropy_j_kg_k,
        s.cp_equilibrium_j_kg_k,
        s.cp_frozen_j_kg_k,
        s.gamma_s,
        s.molecular_weight_kg_kmol,
        station.velocity_m_s,
        station.mach,
        station.sonic_velocity_m_s,
    ];
    for (i, (&a, &b)) in actual.iter().zip(expected).enumerate() {
        if i == 6 && !s.equilibrium {
            continue;
        }
        close(a, b, &format!("{label}, field {i}"));
    }
    assert_eq!(s.equilibrium, expected[13] != 0.0);
    assert!(s.element_residual < 2e-5);
    assert!(s.constraint_residual < 2e-5);
}

fn closure(up: &ShockStation, down: &ShockStation, upstream_velocity: f64) {
    let (a, b) = (&up.state, &down.state);
    let (u, v) = (upstream_velocity, down.velocity_m_s);
    let mass = a.density_kg_m3 * u;
    let momentum = a.pressure_pa + mass * u;
    let energy = a.enthalpy_j_kg + u * u / 2.;
    assert!((mass - b.density_kg_m3 * v).abs() / mass < 5e-5);
    assert!((momentum - b.pressure_pa - b.density_kg_m3 * v * v).abs() / momentum < 5e-5);
    assert!((energy - b.enthalpy_j_kg - v * v / 2.).abs() / energy.abs().max(u * u).max(1.) < 5e-5);
}

#[test]
fn native_shock_goldens_and_conservation() {
    for line in GOLDENS.lines().filter(|l| !l.is_empty()) {
        let mut tokens = line.split_whitespace();
        let kind = tokens.next().unwrap();
        let values: Vec<f64> = tokens.map(|x| x.parse().unwrap()).collect();
        let (solver, weights) = model(kind);
        let reflected = values[2] != 0.;
        let speed = if kind == "rp7" {
            ShockSpeed::Velocity(values[1])
        } else {
            ShockSpeed::Mach(values[1])
        };
        let result = solver
            .shock(
                &weights,
                300.,
                values[0],
                speed,
                reflected,
                values[3] != 0.,
                values[4] != 0.,
            )
            .unwrap_or_else(|e| panic!("{kind} {:?}: {e}", &values[..5]));
        let stations: Vec<_> = [&result.station1, &result.station2]
            .into_iter()
            .chain(result.station5.as_ref())
            .collect();
        assert_eq!(stations.len(), if reflected { 3 } else { 2 });
        let mut offset = 5;
        for (i, st) in stations.iter().enumerate() {
            let label = format!("{kind} {:?} station {i}", &values[..5]);
            check_station(st, &values[offset..offset + 14], &label);
            offset += 14;
            let count = values[offset] as usize;
            offset += 1;
            // Absolute composition tolerance accounts for native's trace cutoff.
            for _ in 0..count {
                let index = values[offset] as usize;
                let name = SPECIES[index];
                let x = st.state.mole_fractions.get(name).copied().unwrap_or(0.);
                let y = st.state.mass_fractions.get(name).copied().unwrap_or(0.);
                assert!((x - values[offset + 1]).abs() < 1e-6, "{label} X({name})");
                assert!((y - values[offset + 2]).abs() < 1e-6, "{label} Y({name})");
                offset += 3;
            }
            close(st.state.mole_fractions.values().sum(), 1., &label);
            close(st.state.mass_fractions.values().sum(), 1., &label);
        }
        let mut ratios = vec![
            result.p2_p1,
            result.t2_t1,
            result.m2_m1,
            result.rho2_rho1,
            result.v2_m_s,
        ];
        if reflected {
            ratios.extend([
                result.p5_p2.unwrap(),
                result.t5_t2.unwrap(),
                result.m5_m2.unwrap(),
                result.rho5_rho2.unwrap(),
                result.u5_plus_v2_m_s.unwrap(),
            ]);
            closure(
                &result.station2,
                result.station5.as_ref().unwrap(),
                result.u5_plus_v2_m_s.unwrap(),
            );
        } else {
            assert!(
                result.p5_p2.is_none()
                    && result.t5_t2.is_none()
                    && result.m5_m2.is_none()
                    && result.rho5_rho2.is_none()
                    && result.u5_plus_v2_m_s.is_none()
            );
        }
        for (&a, &b) in ratios.iter().zip(&values[offset..]) {
            close(a, b, kind);
        }
        assert_eq!(ratios.len(), values.len() - offset);
        closure(
            &result.station1,
            &result.station2,
            result.station1.velocity_m_s,
        );
    }
}

#[test]
fn native_nonconvergence_never_returns_a_retained_incident_or_reflected_state() {
    let (solver, weights) = model("rp7");
    for p in [1333.2236842105262, 2666.4473684210525] {
        for reflected in [false, true] {
            assert!(matches!(
                solver.shock(
                    &weights,
                    300.,
                    p,
                    ShockSpeed::Velocity(1000.),
                    reflected,
                    false,
                    false
                ),
                Err(Error::Convergence(_))
            ));
        }
    }
}

#[test]
fn shock_rejects_invalid_inputs_and_reference_only_reactants() {
    let (solver, weights) = model("rp7");
    for speed in [
        ShockSpeed::Mach(0.9),
        ShockSpeed::Mach(1.),
        ShockSpeed::Velocity(-1000.),
        ShockSpeed::Velocity(f64::INFINITY),
        ShockSpeed::Mach(f64::NAN),
    ] {
        assert!(
            solver
                .shock(&weights, 300., 1e5, speed, false, false, false)
                .is_err()
        );
    }
    for (w, t, p) in [
        (vec![], 300., 1e5),
        (vec![0.; 3], 300., 1e5),
        (vec![1., -1., 1.], 300., 1e5),
        (vec![1., f64::NAN, 1.], 300., 1e5),
        (weights.clone(), f64::NAN, 1e5),
        (weights.clone(), 300., 0.),
        (weights.clone(), 300., f64::INFINITY),
    ] {
        assert!(
            solver
                .shock(&w, t, p, ShockSpeed::Mach(3.), false, false, false)
                .is_err()
        );
    }
    let custom =
        Reactant::custom("H2".into(), [("H".into(), 2.)].into(), 2.01588, 0., 300.).unwrap();
    let solver = Solver::new(vec![custom], false, false, None, vec![]).unwrap();
    assert!(
        solver
            .shock(&[1.], 300., 1e5, ShockSpeed::Mach(3.), false, false, false)
            .is_err()
    );
}

