#[test]
fn frozen_shock_above_20000_k_matches_native() {
    // Native cea==3.3.4 ShockSolver: Ar, T1=15000 K, P1=1 bar, Mach 1.5, incident frozen.
    let solver = Solver::new(
        vec![Reactant::named("Ar").unwrap()],
        true,
        false,
        None,
        vec![],
    )
    .unwrap();
    let r = solver
        .shock(
            &[1.0],
            15000.0,
            1e5,
            ShockSpeed::Mach(1.5),
            false,
            true,
            false,
        )
        .unwrap();
    close(r.station2.state.temperature_k, 20187.080902837, "T2");
    close(r.station2.state.pressure_pa, 272925.975706753, "P2");
}
